  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 6, 10, 8, 5, '{"niche_fit": "Pure skincare brand in the directory''s core niche, with hero products (spray serum, sunscreens, capsule creams) that suit routine and review content.", "ugc_evidence": "The brand itself announced TikTok Shop Open Collaborations for creators through its own ambassador account, and its official shop carries heavy creator-driven sales content.", "compensation": "Creator commission is confirmed by the brand''s launch announcement, but no rate is published anywhere fetched, so compensation scores low.", "contact_access": "Open Collaborations inside TikTok Shop plus a dedicated brand ambassador Instagram account give creators a direct route in.", "opportunity_availability": "The US TikTok Shop open-collaboration route was publicly launched and is live now.", "credibility": "Official brand shop with a named US seller entity (DALBA USA CORP), 4.7 shop rating and a flagship product the brand credits with 50M bottles sold."}'::jsonb);
