  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://imageskincare.com/pages/image-affiliate-program', 'brand_site', 'affiliate', 'IMAGE Skincare''s own affiliate program page says the program is open to creators, estheticians and partners, offers personalized affiliate links and storefronts (including a LoudCrowd personalized storefront), routes content via TikTok, Amazon Storefront, LTK and ShopMy, states there is no follower requirement (''We welcome creators, influencers, and skincare enthusiasts''), and requires no product gifting or free seeding to join. The page does not publish a commission rate, so the rate is recorded as unpublished and the cap as unknown. Checked 2026-11-21.', 'verified', now());
