  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Shopper.com/partnerships/touchland-com-affiliate-program', 'affiliate_network', 'compensation', 'Shopper.com''s partnership listing for touchland.com describes a CPA affiliate program paying ''up to 4.66%'' per sale with deeplinks and instant approval via Shopper. ''Up to'' is a ceiling, not a flat published rate, and the listing does not name the underlying network, so commission_rate is recorded as null and the route is flagged needs_review; no cap statement appears, so the cap is unknown. Checked 2026-11-21.', 'needs_review', now());
