  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 10, 5, 7, 7, 4, '{"niche_fit": "Hand care and fragrance mists \u2014 beauty-adjacent personal care rather than core skincare or color cosmetics.", "ugc_evidence": "A creator-relevant affiliate route is listed and the brand is heavily social-led, but no structured creator program was found on fetched pages.", "compensation": "Only a ceiling (''up to 4.66%'') is published through the listing, so the rate is unrecorded.", "contact_access": "Join route is through the Shopper partnership listing with instant approval; no public partnerships email was found.", "opportunity_availability": "Listing advertises instant approval, keeping the route open to new creators.", "credibility": "Established US brand with national retail distribution and an official direct store."}'::jsonb);
