  insert into public.brands (name, website, description, country, status) values ('Blissoma', 'https://blissoma.com', 'Independent botanical skincare company based in St. Louis, Missouri, founded by herbal chemist Julie Longyear, making small-batch whole-plant cleansers, toners and mists, moisturizers, facial oils, serums, masks and exfoliating treatments.', 'United States', 'published') returning id into bid;
