  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/blissoma-holistic-skincare/', 'affiliate_network', 'compensation', 'Lasso''s affiliate directory lists the Blissoma Holistic Skincare program at a flat 10% per sale with a 60-day cookie, in the Beauty and Skin Care categories. No earnings-cap statement appears on the listing, so the cap is recorded as unknown. Checked 2026-11-21.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/88346/blissoma-com-affiliate-program', 'affiliate_network', 'general', 'Sovrn Commerce''s merchant page describes Blissoma as an independent botanical skincare company based in St. Louis, Missouri, founded by herbal chemist and formulator Julie Longyear; Sovrn notes the current rate through its own network could not be independently verified, so the recorded 10% rests on the Lasso directory listing. Checked 2026-11-21.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 8, 11, 7, 7, 3, '{"niche_fit": "Botanical facial skincare squarely in the skincare niche, though a small indie label.", "ugc_evidence": "An affiliate program exists, but no structured creator or UGC program was found on fetched pages.", "compensation": "A flat 10% per sale with a 60-day cookie is published in the affiliate directory \u2014 a real, recorded rate.", "contact_access": "Join route is through the affiliate directory/network; no public partnerships email was found on fetched pages.", "opportunity_availability": "Program is listed as open to join through the network.", "credibility": "Small independent brand; identity and founder are documented on the Sovrn merchant page, but scale is limited."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Comfrt', 'https://comfrt.com', 'DTC loungewear brand founded in 2022 around a weighted, oversized hoodie with a mental-health mission, now selling hoodies, sweatpants, blankets, athleisure and matching dog hoodies. Its growth is creator-led: an open Ambassador Program pays commission on sales driven through personal links, and the brand is reported to be TikTok Shop''s top lifestyle and apparel brand.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'ambassador@comfrt.com', null, 'https://comfrt.com/en-gb/content/ambassador-program-terms-and-conditions', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own ambassador program', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://comfrt.com/en-gb/content/ambassador-program-terms-and-conditions.', 'https://comfrt.com/en-gb/content/ambassador-program-terms-and-conditions', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Comfrt Ambassador Program', 'https://comfrt.com/en-gb/content/ambassador-program-terms-and-conditions', 'https://comfrt.com/en-gb/content/ambassador-program-terms-and-conditions', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://comfrt.com/en-gb/content/ambassador-program-terms-and-conditions', 'brand_page', 'affiliate', 'Comfrt''s own Ambassador Program Terms & Conditions (fetched in full) state that accepted ambassadors earn ten percent (10%) of the Gross Revenue (amount paid for merchandise, excluding shipping and tax) on purchases made through their unique Ambassador Link, and give ambassador@comfrt.com as the program contact. The terms state NO earnings cap, so the cap is recorded as unknown, not uncapped - a third-party coupon page''s ''no cap on earnings'' claim does not count under the strict filter.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://hashtagcollabz.com/stories/comfrt', 'listing', 'ugc_collab', 'Collabz case study (fetched) reports Comfrt''s ambassador program counted more than 250,000 ambassadors and a TikTok affiliate community of about 600,000, with 9,393 creators posting 50,000+ TikTok Shop videos in one 30-day stretch of 2026 - absolute big-number evidence, so creator saturation is recorded as high. It also corroborates the standard 10% ambassador commission and $500M+ in sales within three years.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 20, 13, 13, 9, 4, '{"niche_fit": "Pure loungewear/apparel brand built for social-first fashion creators - squarely in the fashion UGC niche.", "ugc_evidence": "Creator-led by design: 250,000+ ambassadors and ~600,000 TikTok affiliates reported, with tens of thousands of creator videos per month.", "compensation": "10% of gross merchandise revenue per its own published terms; no cap stated anywhere in the terms, so cap is unknown, not uncapped.", "contact_access": "Published program email (ambassador@comfrt.com) in the brand''s own terms plus an open application route.", "opportunity_availability": "Program is open to customers as well as creators, applications reviewed on a rolling basis.", "credibility": "Reported $500M+ sales in three years and TikTok Shop''s top apparel brand, per a third-party case study - strong but not audited."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Intrepid Travel', 'https://www.intrepidtravel.com', 'Small-group adventure tour operator founded in 1989 and now one of the world''s largest travel B Corporations, running 1,000+ itineraries across all seven continents with local leaders and a responsible-travel mission. Its affiliate program explicitly recruits individual creators and travel advocates as well as organizations.', 'Australia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.intrepidtravel.com/us/affiliate', 'https://www.intrepidtravel.com/us/affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.intrepidtravel.com/us/affiliate.', 'https://www.intrepidtravel.com/us/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Intrepid Travel affiliate program (Impact)', 'https://www.intrepidtravel.com/us/affiliate', 'https://www.intrepidtravel.com/us/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.intrepidtravel.com/us/affiliate', 'brand_page', 'affiliate', 'Intrepid''s own affiliate sign-up page (fetched in full) describes commission on every successful booking, a dedicated affiliate management team and real-time tracking, with separate application paths for organizations and for individual creators/travel advocates; both ''Apply now'' buttons route to app.impact.com, identifying Impact as the network. The page publishes no rate, cap or creator count.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/intrepid-travel/', 'affiliate_network', 'affiliate', 'Lasso''s Intrepid Travel listing (fetched in full) states a 4% commission per sale and a 60-day cookie duration. No fetched source states an earnings cap or publishes creator counts, so both are recorded as unknown. (Travel-agent channel commissions of 15-17% reported elsewhere are trade rates, not the creator affiliate program, and are excluded.)', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 12, 8, 8, 9, 5, '{"niche_fit": "Adventure group tours are a core travel-creator category; the brand recruits creators and travel advocates by name.", "ugc_evidence": "Own affiliate page speaks directly to content creators and storytellers and offers content-experience partnerships, but publishes no creator counts.", "compensation": "4% per sale (Lasso listing) on high-value tour bookings with a long 60-day cookie; no cap statement, so cap is unknown.", "contact_access": "Own affiliate page with a dedicated affiliate team; application via Impact; no public email published.", "opportunity_availability": "Program is live with open applications for both organizations and individual creators.", "credibility": "Operating since 1989, certified B Corporation, 1,000+ itineraries worldwide."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hostelworld', 'https://www.hostelworld.com', 'Global hostel-booking platform listing 36,000+ properties in around 180 countries, aimed at backpackers and budget travellers. Its affiliate programme is free to join, runs on Partnerize, and pays CPA commission calculated as a percentage of the deposit Hostelworld earns on each completed booking.', 'Ireland', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@hostelworld.com', null, 'https://partners.hostelworld.com/faqs/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Partnerize', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://partners.hostelworld.com/faqs/.', 'https://partners.hostelworld.com/faqs/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Hostelworld Affiliate Programme (Partnerize)', 'https://partners.hostelworld.com/faqs/', 'https://partners.hostelworld.com/faqs/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partners.hostelworld.com/faqs/', 'brand_page', 'affiliate', 'Hostelworld''s own affiliate FAQ (fetched in full) states the programme is free to join, commission is CPA calculated as a percentage of the deposit earned by Hostelworld per booking (earned once the booking is completed), tracking uses a 30-day cookie with last-click attribution, sign-up is via Partnerize, and the affiliate team email is affiliates@hostelworld.com. The FAQ publishes no percentage figure, cap or creator count.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/hostelworld/', 'listing', 'compensation', 'Third-party figures for the percentage conflict - commonly cited as 40% of the booking deposit, while other directories cite 18-22% of Hostelworld''s booking commission - so commission_rate is recorded as null with the basis documented: a percentage of the deposit Hostelworld earns per completed booking. No source states an earnings cap.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 10, 7, 13, 8, 5, '{"niche_fit": "The default hostel-booking platform for backpacker and budget-travel creators.", "ugc_evidence": "Open affiliate programme pitched at travel sites and creators, but no dedicated creator program page or published creator counts.", "compensation": "Percentage-of-deposit CPA confirmed on the brand''s own FAQ, but the percentage itself is unpublished there and third-party figures conflict (40% of deposit vs 18-22% of booking commission), so the rate is null; no cap stated.", "contact_access": "Published affiliate team email (affiliates@hostelworld.com) on the brand''s own partner site, plus Partnerize application.", "opportunity_availability": "Free to join via Partnerize, application reviewed by Hostelworld.", "credibility": "Long-established global OTA focused on hostels, 36,000+ properties."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TrustedHousesitters', 'https://www.trustedhousesitters.com', 'Membership platform matching pet owners with vetted house and pet sitters in 130+ countries, so members travel while pets stay at home. Its affiliate program targets experienced content creators and publishers (5,000+ followers or monthly views) and runs through Awin/CJ.', 'United Kingdom', 'published') returning id into bid;
