  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/trustedhousesitters/.', 'https://getlasso.co/affiliate/trustedhousesitters/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TrustedHousesitters affiliate program (Awin)', 'https://getlasso.co/affiliate/trustedhousesitters/', 'https://getlasso.co/affiliate/trustedhousesitters/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.trustedhousesitters.com/hc/en-gb/articles/8624479380509-Is-there-an-affiliate-program', 'brand_page', 'contact', 'TrustedHousesitters'' own support article (fetched in full) confirms the affiliate program for content creators and publishers and gives partnerships@trustedhousesitters.com for affiliate and partnership applications. A companion support article states affiliates need 5,000+ followers on one channel and/or 5,000 monthly blog views.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/trustedhousesitters/', 'affiliate_network', 'compensation', 'Rate figures conflict across fetched sources: Lasso lists 20% per sale with a 30-day cookie, its US listing shows a $28 flat per sale, other sources cite up to 40% per membership and a $100 flat homeowner bounty - so commission_rate is recorded as null with the conflict documented. Listings place the program on Awin (some also cite CJ). No source states an earnings cap or absolute creator counts.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 6, 12, 7, 5, '{"niche_fit": "House/pet sitting is a distinctive, content-rich travel niche (slow travel, pet care, digital-nomad life).", "ugc_evidence": "Affiliate program explicitly aimed at content creators, plus a separate smaller-creator Tailblazers scheme; no creator counts published.", "compensation": "Published figures conflict (20% per sale vs $28 flat US vs up to 40% vs $100 flat homeowner bounty), so the rate is null; no cap stated.", "contact_access": "Published partnerships email for affiliate applications on the brand''s own support site, plus network application.", "opportunity_availability": "Open to creators meeting a 5,000-follower / 5,000-monthly-view threshold - a real but modest gate.", "credibility": "Established membership platform operating in 130+ countries."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('12Go', 'https://12go.asia', 'Online travel agency founded in 2013 for booking trains, buses, ferries, flights and transfers across 100+ countries, strongest in Southeast Asia and Oceania. Its affiliate program pays partners 50% of 12Go''s profit per booking and is also distributed through Travelpayouts.', 'Singapore', 'published') returning id into bid;
