  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Travelpayouts', 50, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://agent.12go.asia/.', 'https://agent.12go.asia/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, '12Go affiliate program (own agent program / Travelpayouts)', 'https://agent.12go.asia/', 'https://agent.12go.asia/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://agent.12go.asia/', 'brand_page', 'affiliate', '12Go''s own affiliate program page (fetched in full) states: ''We give our partners 50% of the total profit. The average commission is $3 per booking.'' It also confirms a 30-day last-click cookie, payouts via PayPal/Wise/bank transfer, no website required (social media communities qualify), free joining, and the contact affiliate@12go.asia. The page states no earnings cap and no creator count.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/train-affiliate-programs/', 'affiliate_network', 'affiliate', 'Travelpayouts'' program roundup corroborates 12Go''s 50% revenue share on on-site sales across 100+ countries and notes the same ~$3 average per booking; other Travelpayouts pages express the effective rate as roughly 4-5.5% of booking value. The 50% figure is a share of 12Go''s profit, not of the booking price.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 9, 12, 12, 9, 4, '{"niche_fit": "Multi-modal ground and ferry transport booking is core backpacker and Asia-travel creator content.", "ugc_evidence": "Program explicitly open to travel sites, blogs and social media communities; no creator counts published.", "compensation": "50% of 12Go''s profit per booking per its own page (revenue share basis; ~$3 average per booking, roughly 4-5.5% of booking value). No cap statement, so cap is unknown.", "contact_access": "Published affiliate email (affiliate@12go.asia) and support contact on the brand''s own agent portal.", "opportunity_availability": "Free to join, no website required, applications via the agent portal or Travelpayouts.", "credibility": "Operating since 2013, 3M+ travellers and 180,000+ positive reviews reported by its network listing."}'::jsonb);
