  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/mvmt-watches/', 'affiliate_network', 'affiliate', 'Lasso''s MVMT Watches listing (fetched in full) states an 8% commission per sale and a 30-day cookie, categorized under Fashion/Watch/Jewelry; its join button routes to publisherpro.flexoffers.com, identifying FlexOffers as the network. A Shopper listing''s vaguer 5-10% range brackets the same figure. No earnings cap or creator count is published, so both are recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 10, 11, 7, 8, 5, '{"niche_fit": "Watches, eyewear and jewelry are staple fashion-accessory creator categories.", "ugc_evidence": "Public affiliate program on a major network; brand was built on social/influencer marketing, but no creator program page or counts found.", "compensation": "8% per sale (Lasso listing); no cap statement published, so cap is unknown.", "contact_access": "Application runs through the FlexOffers network listing; no public creator contact email published.", "opportunity_availability": "Program is live and joinable through FlexOffers signup.", "credibility": "Established DTC accessories brand founded in 2013, widely distributed."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Omio', 'https://www.omio.com', 'Berlin-founded travel platform (formerly GoEuro) for comparing and booking trains, buses, flights and ferries from 1,000+ carriers, strongest across Europe. Its affiliate program runs through Travelpayouts (also listed on Impact) and pays on booking value.', 'Germany', 'published') returning id into bid;
