  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Omio affiliate program (Travelpayouts)', 'https://www.travelpayouts.com/blog/goeuro-affiliate-program/', 'https://www.travelpayouts.com/blog/goeuro-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/goeuro-affiliate-program/', 'affiliate_network', 'affiliate', 'Travelpayouts'' own Omio program page (fetched in full) headlines a 6% reward on booking value with a 30-day last-click cookie, but its dual-payout detail describes a EUR0.26 lead payment plus a 3.4% booking conversion - an internal conflict. Omio''s own affiliate page confirms the programme exists but publishes no rate, referring applicants to its partner team.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/omio/', 'listing', 'compensation', 'Lasso lists Omio at a 2-8% per-sale range with a 30-day cookie, consistent with a market-dependent structure rather than one flat rate. Because the fetched figures conflict (6% headline vs 3.4% booking conversion vs 2-8% range), commission_rate is recorded as null. No source states an earnings cap or creator counts.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 9, 6, 7, 8, 5, '{"niche_fit": "Multi-modal European trip planning is core travel-creator content; Omio explicitly accepts social and content partners.", "ugc_evidence": "Long-running affiliate program open to content sites and social channels; no dedicated creator program or published counts.", "compensation": "Figures conflict across fetched sources (6% headline vs 3.4% booking conversion plus lead fee vs 2-8% range), so the rate is null; no cap stated.", "contact_access": "Application through Travelpayouts and Omio''s own affiliate page; no public email recovered from fetched pages.", "opportunity_availability": "Program is live on Travelpayouts with open publisher signup.", "credibility": "Major European travel platform founded in 2013, 25M+ monthly visits reported by its network page."}'::jsonb);
