  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ca.puravidabracelets.com/pages/affiliate-program-terms-conditions', 'brand_page', 'affiliate', 'Pura Vida''s own Affiliate Program Terms & Conditions (fetched in full) confirm a live affiliate program: applications reviewed within 48 hours, sales lock 30 days after transaction, and ''All payments will be processed by ShareASale'', with program coupon codes distributed through the ShareASale Deals Database - identifying ShareASale as the network. The terms publish no headline commission percentage and no earnings cap.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://runtheaffiliatemarket.com/can-you-make-money-with-the-pura-vida-affiliate-program/', 'listing', 'compensation', 'Rate figures conflict: a program review cites up to 12% per the ShareASale profile (an ''up to'' ceiling, not a flat rate), while a Shopper partnership listing shows 0.7% - so commission_rate is recorded as null with the conflict documented. Note the brand''s published terms are dated 2016 and exclude affiliates in several US states for tax-nexus reasons.', 'needs_review', now());
