  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Little Spoon Affiliate Program (Impact) — % of first-time sales, rate not published by the brand', 'https://www.littlespoon.com/affiliate-program', 'https://www.littlespoon.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.littlespoon.com/affiliate-program', 'official_site', 'affiliate', 'Little Spoon''s own affiliate page, fetched in full: affiliates earn money on each new purchase through a personalized link, are ''compensated a % of every first time sale'', get paid monthly, and can earn quarterly bonuses; the application button routes to app.impact.com. The page never states the percentage, so commission_rate is null. No cap statement or creator count is published.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/little-spoon/', 'network_listing', 'compensation', 'Third-party listings conflict: Lasso lists 15% per sale with a 90-day cookie; other directories list a $15 flat per sale via ShareASale, ~10% on new customers, or 20% via an Impact sub-network. Because the figures conflict and the brand''s own page publishes no rate, the rate is recorded as null rather than guessed.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 9, 11, 9, 4, '["Fresh baby food and kids'' meals are core food/parenting creator content.", "The brand runs an open affiliate page recruiting creators, with early access to launches and quarterly bonuses.", "Compensation is a percentage of first-time sales, but the brand publishes no rate and third-party figures conflict (15% vs $15 flat vs 20%) \u2014 recorded honestly as unpublished.", "Application is one click from the brand''s own affiliate page into Impact.", "Open application route on the brand''s own site.", "Well-known DTC baby-food brand with national retail expansion."]'::jsonb);
