  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'fatty15 Affiliate Program (Impact) — 10% per sale and 10% on recurring subscriptions per the network listing', 'https://linkclicky.com/affiliate-program/fatty15/', 'https://linkclicky.com/affiliate-program/fatty15/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/fatty15/', 'network_listing', 'affiliate', 'LinkClicky''s program listing, fetched in full: platform Impact, application via app.impact.com, commission listed as ''$20, 10% per sale, 10% per recurring subscription'' — i.e. a 10% per-sale rate (with a $20 element in the listed structure and 10% on recurring subscriptions). No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
