  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.facebook.com/dustin.holston.92/posts/pfbid02Ry7YVoMYptxuzFpqHCScjSHGVBNoyZwejKx5odHHXaiAg7qstbJPkzoM3Qtxn31Ml', 'listing', 'ugc_collab', 'A creator''s post screenshotting BodyHealth''s own Instagram outreach: the brand invites aligned creators to join the BodyHealth Affiliate Program and gives the direct signup link bodyhealth.everflowclient.io/affiliate/signup — confirming the program runs on Everflow and actively recruits creators. No rate, cap statement or creator count is published in the outreach.', 'publicly_reported', now());
