  insert into public.brands (name, website, description, country, status) values ('Cerebelly', 'https://cerebelly.com', 'Science-backed baby food brand making nutrient-dense organic purees and bars formulated with key brain-development nutrients, founded by a neuroscientist. Its affiliate listings conflict — a $5 flat per sale via CJ on one directory versus 8% per subscription via Impact on another — so the rate is recorded as unpublished.', 'United States', 'published') returning id into bid;
