  insert into public.brands (name, website, description, country, status) values ('Crumb', 'https://crumb.pet', 'Pet recovery brand built around a stainless-steel QR-code pet tag linked to the pet''s online profile, with an app and premium tracking tiers aimed at ending pet theft and loss. Its own partner program pays commission on every new user referred, with monthly payouts and a dedicated affiliate manager.', null, 'published') returning id into bid;
