  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://crumb.pet/en-us/partners', 'brand_site', 'affiliate_program', 'Crumb''s own Partners, Ambassadors & Affiliates page (fetched in full) states ''No cap on volumes - There''s no limit to what you can earn as a Crumb affiliate'' and repeats in its FAQ: ''There''s no limit to what you can earn as a Crumb affiliate. We offer competitive commission rates'' - an explicit no-earnings-cap statement on the brand''s own page, so commission_cap is recorded as uncapped. No percentage rate is published on the page, so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://crumb.pet/en-us/partners', 'brand_site', 'affiliate_program', 'Program mechanics from the same page: commission on every new user referred, paid monthly by wire transfer or PayPal every 30 days, 365-day attribution on affiliate links, dedicated affiliate manager, real-time dashboard, registration via affiliates.crumb.pet; the page also cites a 4.6/5 rating across 21,437 reviews and ''millions of pets already signed up''. No creator count is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 12, 9, 9, 4, '{"niche_fit": "QR pet ID tags and pet recovery are a core pet-creator topic with strong lost-pet storytelling content.", "ugc_evidence": "The brand runs an open affiliate/ambassador program and explicitly recruits Instagram influencers and creators on its own partner page.", "compensation": "Earnings cap is verified uncapped in the brand''s own words, but no percentage rate is published, so the rate side stays mid-range.", "contact_access": "Open partner registration portal plus a dedicated affiliate manager; no public program email published.", "opportunity_availability": "Registration is open now through affiliates.crumb.pet with monthly payouts.", "credibility": "Established pet-tech brand citing 4.6/5 across 21,437 reviews and millions of pets signed up on its own page."}'::jsonb);
