  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.thermoworks.com/pages/affiliate', 'brand_site', 'affiliate_program', 'ThermoWorks'' own affiliate page (fetched in full) states ''Solid Commissions: Earn 10% on every sale you drive'' with a ''Generous Cookie Period'' of 30 days, plus personalized support, exclusive audience codes, banners and samples; the Apply button routes to Impact (app.impact.com), identifying Impact as the network. The page targets creators with original content in cooking, baking, grilling and brewing. No earnings cap or creator count is stated, so both are recorded as unknown.', 'verified', now());
