  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'REDMAGIC affiliate program (in-house)', 'https://eu.redmagic.gg/pages/redmagic-affiliate-program/', 'https://eu.redmagic.gg/pages/redmagic-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://eu.redmagic.gg/pages/redmagic-affiliate-program/', 'brand_site', 'affiliate_program', 'REDMAGIC''s own affiliate program page (fetched in full) describes an in-house affiliate account that is free to join, with monthly incentive events (extra bonuses and commission-ratio increases), a 45-day order validation and a 30-day cookie. The commission shown varies by platform/region - tiles of 3%, 1.69%, 2.5% and 2% all appear on the page - so no single rate can be recorded and commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://eu.redmagic.gg/pages/redmagic-affiliate-program/', 'brand_site', 'compensation', 'One tile on the same page reads ''No limit / No minimum withdrawal / commission limit'', which is too garbled in layout to certify as an explicit no-earnings-cap statement; commission_cap is therefore honestly recorded as unknown, not uncapped. No creator count is published, so saturation is unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 7, 8, 9, 4, '{"niche_fit": "Gaming phones and mobile-gaming accessories are a core gaming/tech creator category.", "ugc_evidence": "The brand recruits affiliates directly on its own program page and runs monthly incentive events for members; no creator counts published.", "compensation": "Published rates are low and vary by region/platform (1.69%-3%), so no single rate is recorded; the page''s ''no limit'' tile is too ambiguous to certify uncapped, so cap is unknown.", "contact_access": "Application form sits on the brand''s own program page; no public program email published.", "opportunity_availability": "In-house sign-up is free and open on the brand''s regional stores.", "credibility": "Established gaming-phone brand sold through its own regional storefronts worldwide."}'::jsonb);
