  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/dyson/', 'affiliate_directory', 'affiliate_program', 'Lasso''s Dyson listing (fetched in full) states a 1.6% per sale commission with a 25-day cookie across appliance, cleaning and electronics categories, and its join button routes to FlexOffers (publisherpro.flexoffers.com), so the network is recorded as FlexOffers on that evidence.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ancaster.io/offers/dyson', 'affiliate_directory', 'compensation', 'Ancaster''s Dyson program profile reports the program is split across different networks by territory (Rakuten Advertising for the US and Canada, Impact in the UK, Awin in parts of Europe) with rates roughly 1-3% depending on territory, and other directories report up to 2% or 1.2-2.5% ranges. Because published rates conflict, commission_rate is recorded as null. No fetched source publishes an earnings cap or creator count, so both are recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 5, 7, 8, 5, '{"niche_fit": "Premium vacuums, air treatment and hair tools are heavily reviewed home-tech categories.", "ugc_evidence": "Public affiliate programs on major networks; no dedicated creator program page or published creator counts found.", "compensation": "Published figures are low and conflicting (1.6% per Lasso; roughly 1-3% by territory elsewhere), so the rate is recorded as null; no cap stated, so cap is unknown.", "contact_access": "Application runs through network listings; no public creator contact email published.", "opportunity_availability": "Programs are live across several networks by territory.", "credibility": "Global premium appliance brand with very high average order values."}'::jsonb);
